mapper.select:
SELECT rr.reconciliation_run_id, rr.validation_run_id, rr.settlement_month, rr.payment_stage, rr.insurer_id, ins.insurer_name AS insurerName, rr.status, rr.tolerance_policy_version_id, creator.login_id AS createdBy, rr.created_at AS createdAt, rr.started_at AS startedAt, rr.completed_at AS completedAt, rr.finalized_at AS finalizedAt, finalizer.login_id AS finalizedBy, vw.result_count AS targetCount, vw.matched_count AS matchedCount, vw.exception_count AS exceptionCount, vw.expected_total AS expectedTotal, vw.actual_total AS actualTotal, vw.difference_total AS differenceTotal FROM fgc.reconciliation_run rr JOIN fgc.vw_reconciliation_summary vw ON vw.reconciliation_run_id = rr.reconciliation_run_id LEFT JOIN fgc.insurer ins ON ins.insurer_id = rr.insurer_id LEFT JOIN fgc.app_user creator ON creator.user_id = rr.created_by LEFT JOIN fgc.app_user finalizer ON finalizer.user_id = rr.finalized_by
AND rr.settlement_month = #{settlementMonth}
AND rr.payment_stage = #{paymentStage}
ORDER BY rr.created_at DESC, rr.reconciliation_run_id DESC
